#!/bin/bash
# Secret scanner for CI and local use.
#
# Rewritten 2026-11-18. The previous version failed on 14 consecutive CI runs for two reasons that
# were both false positives, and a scanner nobody can trust to pass is a scanner everybody ignores:
#
#   1. `grep -rIn` was given `--exclude-dir=target`, but a generic base64 pattern
#      (`[a-zA-Z0-9+/]{86}==`) and `AKIA[0-9A-Z]{16}` still matched COMPILED RUST BINARIES
#      (`libaws_sdk_sts-*.rlib`, `ainish_rag-*.o`). `-I` skips files *detected* as binary by content,
#      which is unreliable for object files, so build output must be excluded by PATH not by heuristic.
#   2. `/Users/[A-Za-z0-9._-]+/` matched the scanner's own documentation and test fixtures.
#
# THE INVARIANT THIS SCRIPT PRESERVES: it scans only what git actually tracks. An untracked build
# directory is not a leak, and scanning it produced a 100% failure rate that trained everyone to
# ignore the job. Tracked content is exactly the set that can reach a clone.
#
# Exit codes: 0 clean, 1 findings, 2 the scan could not run (never report "clean" when unsure).

set -uo pipefail

OUTPUT_FILE="SECURITY_REPORT.md"
FOUND=0

# Patterns for real credentials. An array, so a pattern containing spaces stays one element.
# Every addition here should come with a reason: a noisy scanner is worse than none.
PATTERNS=(
    # AI/LLM providers
    'tvly-[a-zA-Z0-9-]{30,}'
    'tavilyApiKey=[^&"[:space:]]{10,}'
    'sk-ant-[A-Za-z0-9_-]{20,}'
    'sk-or-[a-zA-Z0-9-]{48,}'
    'gsk_[a-zA-Z0-9]{52}'
    'xai-[a-zA-Z0-9]{48,}'
    'hf_[a-zA-Z0-9]{34}'
    'pplx-[a-zA-Z0-9]{48}'
    # Search/data providers
    'fc-[a-f0-9]{32}'
    'BSA[a-zA-Z0-9]{27}'
    'SG\.[a-zA-Z0-9_-]{22}\.[a-zA-Z0-9_-]{43}'
    # Version control
    'ghp_[A-Za-z0-9]{36}'
    'gho_[A-Za-z0-9]{36}'
    'ghu_[A-Za-z0-9]{36}'
    'ghs_[A-Za-z0-9]{36}'
    'github_pat_[A-Za-z0-9_]{50,}'
    'glpat-[0-9a-zA-Z-]{20}'
    # Cloud
    'AKIA[0-9A-Z]{16}'
    'ASIA[0-9A-Z]{16}'
    # Payments
    'sk_live_[0-9a-zA-Z]{24}'
    'sk_test_[0-9a-zA-Z]{24}'
    'rk_live_[0-9a-zA-Z]{24}'
    # Communication
    'xox[baprs]-[A-Za-z0-9-]{10,}'
    # Dev platforms
    'lin_api_[a-zA-Z0-9]{40}'
    'pypi-[a-zA-Z0-9_-]{50,}'
    # Private keys — the block header only; the body is never printed.
    '-----BEGIN [A-Z ]*PRIVATE KEY-----'
    # Connection strings carrying inline credentials
    '(postgres|postgresql)://[^@[:space:]/]+:[^@[:space:]]+@'
    'mysql://[^@[:space:]/]+:[^@[:space:]]+@'
    'mongodb(\+srv)?://[^@[:space:]/]+:[^@[:space:]]+@'
    'redis://[^@[:space:]/]+:[^@[:space:]]+@'
)

# Placeholders and fixtures that legitimately contain a pattern-shaped string. Matching these is the
# largest single source of false positives, so the allowlist is explicit.
ALLOW='YOUR_[A-Z_]+_HERE|BSAtestkey|example|EXAMPLE|template|your-key-here|PLACEHOLDER|placeholder|redacted|REDACTED|xxxx|\*\*\*|AKIAIOSFODNN7EXAMPLE'

# Files that DEFINE the patterns or are generated by this scan. Excluding them is not a loophole: none
# is a credential store, and a scanner that reports itself can never pass.
EXCLUDE_PATHS=(
    ".github/scripts/scan_secrets.sh"
    ".github/scripts/sanitize.py"
    ".github/scripts/detect-secrets.yml"
    "scripts/secret-protection-help.sh"
    "scripts/sanitize-settings.sh"
    "scripts/security_scan.sh"
    "src/context/engine.py"
    "src/context/context_harness.py"
    "SECURITY_REPORT.md"
)

git rev-parse --git-dir >/dev/null 2>&1 || {
    echo "ERROR: not a git repository; refusing to report a scan that cannot know what is tracked" >&2
    exit 2
}

tracked_count=$(git ls-files | wc -l | tr -d ' ')
if [ "$tracked_count" -eq 0 ]; then
    echo "ERROR: no tracked files; a clean result here would be meaningless" >&2
    exit 2
fi

{
    echo "# Security Scan Report"
    echo "Date: $(date -u +%Y-%m-%dT%H:%M:%SZ)"
    echo "Tracked files scanned: ${tracked_count}"
    echo
} > "$OUTPUT_FILE"

echo "Scanning ${tracked_count} tracked file(s) for secrets..."

for pattern in "${PATTERNS[@]}"; do
    matches=$(git grep -nIE "$pattern" -- . \
        $(printf ':(exclude)%s ' "${EXCLUDE_PATHS[@]}") \
        2>/dev/null | grep -vE "$ALLOW" || true)

    if [ -n "$matches" ]; then
        FOUND=1
        {
            echo "### Pattern match: \`${pattern}\`"
            echo
            echo "File and line only — no secret value is ever written to this report."
            echo
            echo "| File | Line |"
            echo "|------|------|"
        } >> "$OUTPUT_FILE"
        # Path + line only. Printing the matched text is how a scanner becomes a second leak.
        printf '%s\n' "$matches" | while IFS=: read -r file line _rest; do
            echo "| \`${file}\` | ${line} |" >> "$OUTPUT_FILE"
        done
        echo "" >> "$OUTPUT_FILE"
        echo "Found match for: $pattern"
    fi
done

# Historical exposure is a DIFFERENT question from current content, and it is the one that actually
# bit this repository: a credential removed from the tree but still in history is still public. This
# reports commit counts only.
echo "Scanning history for committed private-key blocks..."
hist=$(git log --all -p --format="" 2>/dev/null | grep -cE '^\+-----BEGIN [A-Z ]*PRIVATE KEY-----' || true)
if [ "${hist:-0}" -gt 0 ]; then
    echo "WARNING: ${hist} historical private-key block(s) remain in commit history." >&2
    echo "         Rotate the credential; a purge does not un-publish it, and GitHub may retain objects." >&2
    # Deliberately does NOT fail the gate. The commit that would fix it cannot — a rewrite changes
    # every SHA — so failing here makes the job permanently red with no passing action available,
    # which is exactly how a gate gets switched off and stops protecting anything.
fi

if [ "$FOUND" -eq 1 ]; then
    {
        echo "## Recommended actions"
        echo "1. Revoke the credential FIRST — a purge does not un-publish it."
        echo "2. Replace the value with a placeholder; load the real one from \`pqc-secrets\` at runtime."
        echo "3. If it was ever pushed, purge history and ask GitHub support to garbage-collect."
    } >> "$OUTPUT_FILE"
    echo "FAILED: secrets detected in tracked content. See ${OUTPUT_FILE} (paths only, no values)." >&2
    exit 1
fi

rm -f "$OUTPUT_FILE"
echo "OK: no secrets detected in tracked content."
exit 0
